import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"常见问题对照表","description":"MiniTavern 连接 Ollama/LM Studio 测连失败、超时、CORS、防火墙等常见问题对照与处理。","frontmatter":{"title":"常见问题对照表","description":"MiniTavern 连接 Ollama/LM Studio 测连失败、超时、CORS、防火墙等常见问题对照与处理。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"常见问题对照表 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 连接 Ollama/LM Studio 测连失败、超时、CORS、防火墙等常见问题对照与处理。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/troubleshoot"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/troubleshoot"}]]},"headers":[],"relativePath":"troubleshoot.md","filePath":"troubleshoot.md","lastUpdated":1787117554000}'),o={name:"troubleshoot.md"};function l(i,t,h,n,c,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="常见问题对照表" tabindex="-1">常见问题对照表 <a class="header-anchor" href="#常见问题对照表" aria-label="Permalink to &quot;常见问题对照表&quot;">​</a></h1><p>按现象查找；仍不行可在 App <strong>设置 → 帮助与反馈 → 问题反馈</strong> 提交（可附截图与问题日志），或用 <strong>反馈邮箱</strong>。请尽量写清：系统、工具（Ollama / LM Studio / KoboldCPP 等）、Base URL（可打码 IP 后两段）、报错原文。</p><h2 id="连接-测连" tabindex="-1">连接 / 测连 <a class="header-anchor" href="#连接-测连" aria-label="Permalink to &quot;连接 / 测连&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>处理</th></tr></thead><tbody><tr><td>连接超时</td><td>不在同一 Wi‑Fi、防火墙拦端口、服务未监听 <code>0.0.0.0</code></td><td>确认同网；放行端口；按各工具「开服务 / 局域网」章节操作</td></tr><tr><td>立刻失败 / 无法连接</td><td>IP 错、端口错、服务没开</td><td>电脑浏览器先打开 <code>http://IP:端口/v1/models</code>；核对 Base URL</td></tr><tr><td>填了 localhost 仍失败</td><td>手机上的 localhost 是手机自己</td><td>改成电脑局域网 IP</td></tr><tr><td>401 / 密钥错误</td><td>少数本地栈校验 Key</td><td>填任意非空占位，或按该工具文档关闭鉴权</td></tr><tr><td>404 / 模型不存在</td><td>模型名与本地不一致</td><td><code>ollama list</code> 或各工具 <code>/v1/models</code> 复制 <strong>完整 id</strong></td></tr><tr><td>有响应但聊天空白/报错</td><td>兼容性、超时过短、模型未加载</td><td>增大超时；确认模型已 load；换较小模型验证通路</td></tr></tbody></table><h2 id="网络与系统" tabindex="-1">网络与系统 <a class="header-anchor" href="#网络与系统" aria-label="Permalink to &quot;网络与系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>处理</th></tr></thead><tbody><tr><td>电脑能连、手机不能</td><td>访客 Wi‑Fi 隔离、AP 隔离</td><td>改用主网络；临时用手机热点让电脑接入再试</td></tr><tr><td>偶发断开</td><td>电脑休眠、IP 变化</td><td>禁止休眠；重查 IP 并更新连接</td></tr><tr><td>VPN 开启后异常</td><td>分流/虚拟网卡</td><td>测试时先关 VPN 或排除局域网</td></tr></tbody></table><h2 id="url-写法" tabindex="-1">URL 写法 <a class="header-anchor" href="#url-写法" aria-label="Permalink to &quot;URL 写法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>正确示例</th><th>错误示例</th></tr></thead><tbody><tr><td><code>http://192.168.1.8:11434/v1</code></td><td><code>http://localhost:11434/v1</code></td></tr><tr><td><code>http://192.168.1.8:1234/v1</code></td><td><code>http://192.168.1.8:1234/v1/chat/completions</code></td></tr><tr><td><code>http://192.168.1.8:5001/v1</code></td><td><code>https://192.168.1.8:11434/v1</code>（本地未配证书时不要强行 https）</td></tr><tr><td><code>http://192.168.1.8:8080/v1</code></td><td></td></tr></tbody></table><h2 id="http-明文" tabindex="-1">HTTP 明文 <a class="header-anchor" href="#http-明文" aria-label="Permalink to &quot;HTTP 明文&quot;">​</a></h2><p>MiniTavern <strong>Android</strong> 已允许明文 HTTP（局域网常用）。若仍被拦：</p><ul><li>确认 Base URL 是 <code>http://</code> 而非错误协议</li><li>确认系统/厂商网络保护未拦截局域网</li><li>iOS 若遇 ATS 限制，优先保证使用文档中的局域网地址；仍失败请反馈系统版本与报错</li></ul><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>浏览器网页才常受 CORS 限制；<strong>原生 App 直连 API 一般不受 CORS 影响</strong>。若你在电脑浏览器里测前端页面失败，不代表 MiniTavern 会失败——请以 App 内测连为准。</p><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>首字极慢</td><td>换更小量化/更小参数；确认在用 GPU</td></tr><tr><td>生成中途卡住</td><td>增大超时；关其它占显存程序；看电脑端日志是否 OOM</td></tr></tbody></table><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="./manual/errors">使用手册 · 错误代码</a>（测连 / 聊天 API 报错）</li><li><a href="./quickstart">30 分钟通关</a></li><li><a href="./local/tools">工具总览</a> · <a href="./local/models">推荐模型</a></li><li><a href="./ollama/lan">Ollama 局域网</a></li><li><a href="./lmstudio/server">LM Studio Local Server</a></li><li><a href="./koboldcpp/server">KoboldCPP API</a></li><li><a href="./llamacpp/server">llama.cpp server</a></li><li><a href="./connect-app/minitavern">MiniTavern 配置</a></li></ul>',17)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
